WITH base AS (SELECT *, INITCAP(TRIM(device_code)) AS device_code_title FROM device_readings WHERE reading_ts >= TO_DATE('2025-09-01') AND temp_c IS NOT NULL), flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '45' MINUTE THEN 1 ELSE 0 END AS is_new_session FROM base), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT device_code, CASE WHEN session_id >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS session_id_tier, MIN(reading_ts) AS first_seen, COUNT(CASE WHEN device_code = 'DV-04' THEN 1 END) AS dv_04_count FROM sessionized GROUP BY GROUPING SETS ((device_code, CASE WHEN session_id >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END), (device_code), ()) ORDER BY device_code DESC;
